   357  static void print_tags_recursive(const u8 * buf0, const u8 * buf,
   358                                   size_t buflen, size_t depth)
   359  {
   360          int r;
   361          size_t i;
   362          size_t bytesleft = buflen;
   363          const char *classes[4] = {
   364                  "Universal",
   365                  "Application",
   366                  "Context",
   367                  "Private"
   368          };
   369          const u8 *p = buf;
   370
   371          while (bytesleft >= 2) {
   372                  unsigned int cla = 0, tag = 0, hlen;
   373                  const u8 *tagp = p;
   374                  size_t len;
   375
   376                  r = sc_asn1_read_tag(&tagp, bytesleft, &cla, &tag, &len);
   377                  if (r != SC_SUCCESS || (tagp == NULL && tag != SC_ASN1_TAG_EOC)) {
   378                          printf("Error in decoding.\n");
   379                          return;
   380                  }
   381                  hlen = tagp - p;
   382                  if (cla == 0 && tag == 0) {
   383                          printf("Zero tag, finishing\n");
   384                          break;
   385                  }
   386                  print_indent(depth);
   387                  /* let i be the length of the tag in bytes */
   388                  for (i = 1; i < sizeof tag - 1; i++) {
   389                          if (!(tag >> 8*i))
   390                                  break;
   391                  }
   392                  printf("%02X", cla<<(i-1)*8 | tag);
   393
   394                  if ((cla & SC_ASN1_TAG_CLASS) == SC_ASN1_TAG_UNIVERSAL) {
   395                          printf(" %s", tag2str(tag));
   396                  } else {
   397                          printf(" %s %-2u",
   398                                          classes[cla >> 6],
   399                                          i == 1 ? tag & SC_ASN1_TAG_PRIMITIVE : tag & (((unsigned int) ~0) >> (i-1)*8));
   400                  }
   401                  if (!((cla & SC_ASN1_TAG_CLASS) == SC_ASN1_TAG_UNIVERSAL
   402                                          && tag == SC_ASN1_TAG_NULL && len == 0)) {
   403                          printf(" (%"SC_FORMAT_LEN_SIZE_T"u byte%s)",
   404                                          len,
   405                                          len != 1 ? "s" : "");
   406                  }
   407
   408                  if (len + hlen > bytesleft) {
   409                          printf(" Illegal length!\n");
   410                          return;
   411                  }
   412                  p += hlen + len;
   413                  bytesleft -= hlen + len;
   414
   415                  if (cla & SC_ASN1_TAG_CONSTRUCTED) {
   416                          putchar('\n');
   417                          print_tags_recursive(buf0, tagp, len, depth + 2*i + 1);
   418                          continue;
   419                  }
   420
   421                  switch (tag) {
   422                          case SC_ASN1_TAG_BIT_STRING:
   423                                  printf(": ");
   424                                  sc_asn1_print_bit_string(tagp, len, depth + 2*i + 1);
   425                                  break;
   426                          case SC_ASN1_TAG_OCTET_STRING:
   427                                  sc_asn1_print_octet_string(tagp, len, depth + 2*i + 1);
   428                                  break;
   429                          case SC_ASN1_TAG_OBJECT:
   430                                  printf(": ");
   431                                  sc_asn1_print_object_id(tagp, len);
   432                                  break;
   433                          case SC_ASN1_TAG_INTEGER:
   434                          case SC_ASN1_TAG_ENUMERATED:
   435                                  printf(": ");
   436                                  sc_asn1_print_integer(tagp, len);
   437                                  break;
   438                          case SC_ASN1_TAG_IA5STRING:
   439                          case SC_ASN1_TAG_PRINTABLESTRING:
   440                          case SC_ASN1_TAG_T61STRING:
   441                          case SC_ASN1_TAG_UTF8STRING:
   442                                  printf(": ");
   443                                  sc_asn1_print_utf8string(tagp, len);
   444                                  break;
   445                          case SC_ASN1_TAG_BOOLEAN:
   446                                  printf(": ");
   447                                  sc_asn1_print_boolean(tagp, len);
   448                                  break;
   449                          case SC_ASN1_GENERALIZEDTIME:
   450                                  printf(": ");
   451                                  sc_asn1_print_generalizedtime(tagp, len);
   452                                  break;
   453                          case SC_ASN1_UTCTIME:
   454                                  printf(": ");
   455                                  sc_asn1_print_utctime(tagp, len);
   456                                  break;
   457                  }
   458
   459                  if ((cla & SC_ASN1_TAG_CLASS) == SC_ASN1_TAG_APPLICATION) {
   460                          print_hex(tagp, len, depth + 2*i + 1);
   461                  }
   462
   463                  if ((cla & SC_ASN1_TAG_CLASS) == SC_ASN1_TAG_CONTEXT) {
   464                          print_hex(tagp, len, depth + 2*i + 1);
   465                  }
   466
   467                  putchar('\n');
   468          }
   469  }
